import { h3CellForPoint, h3DiskForPoint, H3_ASSIGNMENT_RESOLUTION } from '../src/driver-assignment/h3-index'

describe('H3 assignment index', () => {
  it('converts a Managua point to a valid assignment cell', () => {
    const cell = h3CellForPoint({ latitude: 12.1159, longitude: -86.2478 })

    expect(cell).toMatch(/^89[0-9a-f]+$/)
    expect(cell.length).toBeGreaterThan(10)
    expect(H3_ASSIGNMENT_RESOLUTION).toBe(9)
  })

  it('returns the origin cell and nearby cells for a search ring', () => {
    const center = h3CellForPoint({ latitude: 12.1159, longitude: -86.2478 })
    const disk = h3DiskForPoint({ latitude: 12.1159, longitude: -86.2478 }, 1)

    expect(disk).toContain(center)
    expect(disk.length).toBeGreaterThan(1)
  })
})
